from lib import *
S = SS('q25')
steps = [
    step("重复的来源 1:消费者处理完、确认之前崩溃。消费者 A 取到 order-1001(redelivered=False)业务处理完,在 ack 之前连接断了;消息回到队列,消费者 B 又取到(redelivered=True)并再处理一遍——同一条订单被业务处理了 2 次。至少一次投递(手动 ack)的代价就是消息可能到达不止一次。", t=tl(S(1)), mark=lidx(S(1), '消费者 B', '处理了 2 次'), done=lidx(S(1), '消费者 A'), kv=KV([['崩溃时机', '业务处理完,ack 之前'], ['结果', '消息重新投递,业务执行 2 次'], ['redelivered', '第二次是 True']], ['结果'])),
    step("重复的来源 2:发布端没等到 confirm 就重试。经过代理把 broker → 客户端方向延迟 300 ms,发完消息 100 ms 后切断连接——消息已被 broker 收下,Ack 还在路上:发布端得到 StreamLostError,认为没发成功,此时队列里其实已经有 1 条;重连后重发同一条(同样的 message_id=msg-2)并收到 Ack,队列里变成 2 条。取出来两份都是 redelivered=False——redelivered 标志抓不住发布端造成的重复。", t=tl(S(2)), mark=lidx(S(2), '队列里现在有: 2 条', 'redelivered=False'), done=lidx(S(2), '第一次发布', '这时队列里实际已经有'), b=bars([['重发前队列里', 1, '1 条'], ['重发后队列里', 2, '2 条']], 2, mark=[1], done=[0]), kv=KV([['第一次发布', '消息到了 broker,Ack 在路上被切断'], ['发布端', '以为失败,重发'], ['结果', '2 份,都是 redelivered=False']], ['结果'])),
    step("broker 本身不去重:同一个 message_id=msg-3 连发 3 次,收到 3 条。message_id 只是一个普通的消息属性,RabbitMQ 不会用它去重——要去重只能在消费者(或发布端的发送逻辑)里做。", t=tl(S(3)), mark=lidx(S(3), '收到 3 条'), done=lidx(S(3), '收到 3 条'), kv=KV([['message_id', '普通属性,broker 不用它'], ['去重', '只能应用自己做']], ['去重'])),
    step("消费端幂等:在同一个数据库事务里“记下 message_id + 执行业务”,重复的消息被 message_id 的唯一约束挡掉。1000 条消息里 10% 被重复投递(共 1100 次投递),业务是账户余额 +1:朴素消费者执行了 1100 次,余额 = 1100(应为 1000);幂等消费者同样收到 1100 次投递,业务只执行 1000 次,余额 = 1000。耗时朴素 36 ms、幂等 37 ms,差别在噪声内(sqlite 内存库)。", t=tl(S(4)), mark=lidx(S(4), '朴素消费者', '幂等消费者'), done=lidx(S(4), '耗时'), b=bars([['朴素:余额', 1100, '1100'], ['幂等:余额', 1000, '1000'], ['正确答案', 1000, '1000']], 1100, mark=[0], done=[1, 2]), kv=KV([['朴素', '执行 1100 次,余额 1100(错)'], ['幂等', '执行 1000 次,余额 1000(对)'], ['做法', '同事务内唯一约束']], ['幂等'])),
    step("去重表不能无限长:message_id 要保留到“重复可能出现的最长窗口”过去为止。作为量级参考,100 万个 36 字符的 message_id 放进 sqlite(without rowid)插入 787 ms,库大小约 28.3 MiB。每天几亿条消息时,去重记录要按时间窗口清理,或改用业务上天然唯一的键(订单号 + 操作)。", t=tl(S(5)), mark=lidx(S(5), '100 万个'), done=lidx(S(5), '100 万个'), kv=KV([['100 万个 message_id', '约 28.3 MiB'], ['保留多久', '≥ 重复可能出现的最长窗口'], ['替代', '业务天然幂等键']], ['保留多久'])),
]
A = mkartq('q25', 25, 'RabbitMQ,幂等,重复投递,message_id,至少一次,真实验证,动画演示',
    '在 RabbitMQ 4.3.6 上复现两种重复来源:消费者 ack 前崩溃导致重复处理(redelivered=True)、发布端因 Ack 丢失而重发导致队列里 2 份(都是 redelivered=False);broker 不会按 message_id 去重;用 message_id 唯一约束 + 同事务让 1100 次投递只执行 1000 次,余额 1000;100 万个 message_id 约 28.3 MiB。',
    '至少一次投递意味着消息会重复。重复到底从哪来?redelivered 标志能不能识别?RabbitMQ 会不会帮你去重?消费者怎么做才算幂等?这篇先复现两种重复,再实测一个最小的幂等实现。',
    [('2 次', '消费者在 ack 之前崩溃,同一条订单被业务处理的次数'), ('2 份 / False', '发布端因 Ack 丢失重发后,队列里同一消息的份数,且 redelivered 都是 False'), ('1100 → 1000', '幂等消费者把 1100 次投递中的重复挡掉,余额回到 1000')],
    [('消费端造成的重复', '<p>处理完业务、ack 之前崩溃(或 ack 丢失),broker 会重投该消息,标志 <code>redelivered=True</code>。</p>'),
     ('发布端造成的重复', '<p>消息已到 broker 但 Ack 没回来,发布端重试,队列里就有两份;这两份的 redelivered 都是 False,所以不能靠这个标志去重。</p>'),
     ('broker 不去重', '<p><code>message_id</code> 只是属性,RabbitMQ 不用它去重。</p>'),
     ('幂等消费', '<p>用 message_id(或业务上唯一的键)做唯一约束,和业务操作放在同一个数据库事务里;重复的消息插入失败,业务就不会再执行。</p>'),
     ('代价', '<p>去重记录要保留到重复可能出现的窗口之外,100 万个 id 约 28 MiB,需要定期清理。</p>')],
    steps,
    [ENV_Q + '。第二节经自己写的 TCP 代理:S→C 方向延迟 300 ms,100 ms 后 cut 连接;幂等实验用 sqlite3 内存库模拟业务库;耗时是整个消费 1100 条的时间,单次',
     '没有验证:stream 队列的发布端去重(需要 stream 协议的 producer name);数据库事务与消息 ack 之间的更严格一致(见第 35 篇 Outbox);去重表在分布式数据库、Redis 上的实现;去重窗口的清理策略;多个消费者并发处理同一个 message_id 时的竞争(依赖唯一约束)'],
    '消息幂等')
